import React from "react";
import Sidebar from "./Sidebar";

export default function CustomerDashboard({ onLogout, onViewDetails }) {
  const [active, setActive] = React.useState("dashboard");
  const [searchQuery, setSearchQuery] = React.useState("");
  const [showSearchForm, setShowSearchForm] = React.useState(false);
  const [searchFilters, setSearchFilters] = React.useState({
    name: "",
    location: "",
    city: "",
    pincode: "",
    area: "",
  });
  const searchPanelRef = React.useRef(null);

  React.useEffect(() => {
    const handleClickOutside = (event) => {
      if (showSearchForm && searchPanelRef.current && !searchPanelRef.current.contains(event.target)) {
        setShowSearchForm(false);
      }
    };

    document.addEventListener("mousedown", handleClickOutside);
    document.addEventListener("touchstart", handleClickOutside);

    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
      document.removeEventListener("touchstart", handleClickOutside);
    };
  }, [showSearchForm]);


  const handleSearchStart = () => {
    if (!showSearchForm) {
      setShowSearchForm(true);
      return;
    }

    if (searchQuery.trim()) {
      setShowSearchForm(true);
    }
  };

  const handleSearchHover = () => {
    setShowSearchForm(true);
  };

  const handleSearchMouseLeave = () => {
    setShowSearchForm(false);
  };

  const handleSearchKeyDown = (event) => {
    if (event.key === "Enter") {
      event.preventDefault();
      handleSearchStart();
    }
  };

  const handleFilterChange = (field, value) => {
    setSearchFilters((prev) => ({ ...prev, [field]: value }));
  };

  const dashboardOffers = [
    {
      tag: "Bike Offer",
      title: "Flash Bike Savings",
      subtitle: "Save 20% on premium bike rentals this week.",
      detail: "Highlight your bike fleet with a fast booking boost and extra visibility.",
    },
    {
      tag: "Car Offer",
      title: "Weekend Car Special",
      subtitle: "Extra cashback on weekend car bookings.",
      detail: "Showcase your best car deals for short trips and road trips alike.",
    },
    {
      tag: "SUV Offer",
      title: "Family SUV Promo",
      subtitle: "Get more family group bookings with special SUV pricing.",
      detail: "Promote comfort and space for longer journeys with this offer.",
    },
  ];

  const dashboardStats = [
    {
      icon: "📅",
      label: "Total Bookings",
      value: "12",
      action: "View All",
      accent: "#10b981",
    },
    {
      icon: "🧳",
      label: "Upcoming Trips",
      value: "2",
      action: "View All",
      accent: "#6366f1",
    },
    {
      icon: "✅",
      label: "Completed Trips",
      value: "8",
      action: "View All",
      accent: "#f59e0b",
    },
    {
      icon: "💰",
      label: "Total Spent",
      value: "₹18,750",
      action: "View Details",
      accent: "#8b5cf6",
    },
  ];

  const [offerIndex, setOfferIndex] = React.useState(0);

  const handlePrevOffer = () => {
    setOfferIndex((prev) => (prev - 1 + dashboardOffers.length) % dashboardOffers.length);
  };

  const handleNextOffer = () => {
    setOfferIndex((prev) => (prev + 1) % dashboardOffers.length);
  };

  const popularVehicles = [
    {
      name: "Honda Activa 6G",
      type: "Bike",
      description: "Available now · ₹249/day",
      price: "₹249/day",
      imageUrl: "https://picsum.photos/seed/activa/400/260",
    },
    {
      name: "Maruti Swift",
      type: "Car",
      description: "Available in Koramangala · ₹1299/day",
      price: "₹1299/day",
      imageUrl: "https://picsum.photos/seed/swift/400/260",
    },
    {
      name: "Tata Nexon",
      type: "SUV",
      description: "Ready for 1-day trips · ₹1599/day",
      price: "₹1599/day",
      imageUrl: "https://picsum.photos/seed/nexon/400/260",
    },
    {
      name: "Tempo Traveller",
      type: "Bus",
      description: "Seats 12 · ₹2599/day",
      price: "₹2599/day",
      imageUrl: "https://picsum.photos/seed/tempo/400/260",
    },
    {
      name: "Yamaha R15",
      type: "Bike",
      description: "Sporty ride · ₹699/day",
      price: "₹699/day",
      imageUrl: "https://picsum.photos/seed/r15/400/260",
    },
    {
      name: "Mercedes E-Class",
      type: "Car",
      description: "Premium comfort · ₹3999/day",
      price: "₹3999/day",
      imageUrl: "https://picsum.photos/seed/eclass/400/260",
    },
    {
      name: "Mahindra Scorpio",
      type: "SUV",
      description: "Family-ready · ₹2499/day",
      price: "₹2499/day",
      imageUrl: "https://picsum.photos/seed/scorpio/400/260",
    },
    {
      name: "Mini Bus",
      type: "Bus",
      description: "Tour package · ₹1899/day",
      price: "₹1899/day",
      imageUrl: "https://picsum.photos/seed/minibus/400/260",
    },
    {
      name: "Toyota Innova",
      type: "Car",
      description: "Spacious travel · ₹1799/day",
      price: "₹1799/day",
      imageUrl: "https://picsum.photos/seed/innova/400/260",
    },
    {
      name: "Royal Enfield",
      type: "Bike",
      description: "Cruiser available · ₹899/day",
      price: "₹899/day",
      imageUrl: "https://picsum.photos/seed/enfield/400/260",
    },
    {
      name: "Kia Seltos",
      type: "SUV",
      description: "Stylish ride · ₹1699/day",
      price: "₹1699/day",
      imageUrl: "https://picsum.photos/seed/seltos/400/260",
    },
    {
      name: "Ford Endeavour",
      type: "SUV",
      description: "Adventure ready · ₹2799/day",
      price: "₹2799/day",
      imageUrl: "https://picsum.photos/seed/endeavour/400/260",
    },
    {
      name: "Bajaj Pulsar",
      type: "Bike",
      description: "City commute · ₹599/day",
      price: "₹599/day",
      imageUrl: "https://picsum.photos/seed/pulsar/400/260",
    },
    {
      name: "Skoda Octavia",
      type: "Car",
      description: "Executive sedan · ₹2199/day",
      price: "₹2199/day",
      imageUrl: "https://picsum.photos/seed/octavia/400/260",
    },
    {
      name: "Hyundai Creta",
      type: "SUV",
      description: "Comfortable drive · ₹1599/day",
      price: "₹1599/day",
      imageUrl: "https://picsum.photos/seed/creta/400/260",
    },
    {
      name: "Ashok Leyland",
      type: "Bus",
      description: "Group travel · ₹3299/day",
      price: "₹3299/day",
      imageUrl: "https://picsum.photos/seed/leyland/400/260",
    },
  ];

  const recentBookings = [
    {
      name: "Maruti Wagon R",
      type: "Car",
      description: "Booked today · ₹999/day",
      price: "₹999/day",
      imageUrl: "https://picsum.photos/seed/wagonr/400/260",
    },
    {
      name: "Hero Splendor",
      type: "Bike",
      description: "Booked yesterday · ₹349/day",
      price: "₹349/day",
      imageUrl: "https://picsum.photos/seed/splendor/400/260",
    },
    {
      name: "Toyota Fortuner",
      type: "SUV",
      description: "Booked this morning · ₹3299/day",
      price: "₹3299/day",
      imageUrl: "https://picsum.photos/seed/fortuner/400/260",
    },
    {
      name: "Volvo Bus",
      type: "Bus",
      description: "Booked yesterday · ₹4599/day",
      price: "₹4599/day",
      imageUrl: "https://picsum.photos/seed/volvobus/400/260",
    },
    {
      name: "TVS Apache",
      type: "Bike",
      description: "Booked today · ₹749/day",
      price: "₹749/day",
      imageUrl: "https://picsum.photos/seed/apache/400/260",
    },
    {
      name: "Honda City",
      type: "Car",
      description: "Booked today · ₹1599/day",
      price: "₹1599/day",
      imageUrl: "https://picsum.photos/seed/hondacity/400/260",
    },
    {
      name: "Ford EcoSport",
      type: "SUV",
      description: "Booked yesterday · ₹1799/day",
      price: "₹1799/day",
      imageUrl: "https://picsum.photos/seed/ecosport/400/260",
    },
    {
      name: "Bajaj Avenger",
      type: "Bike",
      description: "Booked today · ₹599/day",
      price: "₹599/day",
      imageUrl: "https://picsum.photos/seed/avenger/400/260",
    },
    {
      name: "Hyundai Verna",
      type: "Car",
      description: "Booked yesterday · ₹1399/day",
      price: "₹1399/day",
      imageUrl: "https://picsum.photos/seed/verna/400/260",
    },
    {
      name: "MG Hector",
      type: "SUV",
      description: "Booked today · ₹1899/day",
      price: "₹1899/day",
      imageUrl: "https://picsum.photos/seed/hector/400/260",
    },
    {
      name: "Tata Super Ace",
      type: "Bus",
      description: "Booked yesterday · ₹2199/day",
      price: "₹2199/day",
      imageUrl: "https://picsum.photos/seed/superace/400/260",
    },
    {
      name: "Royal Enfield Classic",
      type: "Bike",
      description: "Booked today · ₹999/day",
      price: "₹999/day",
      imageUrl: "https://picsum.photos/seed/classic/400/260",
    },
  ];

  const SearchPanel = ({ fullWidth = true }) => (
    <div style={fullWidth ? { ...styles.panel, gridColumn: "1 / -1" } : styles.panel}>
      <div style={styles.panelHeader}>
        <div>
          <h2 style={styles.panelTitle}>Search Vehicles</h2>
          <p style={styles.panelText}>Enter a keyword to open the advanced search form below.</p>
        </div>
      </div>
      <div
        ref={searchPanelRef}
        style={styles.searchWrapper}
        onMouseEnter={handleSearchHover}
        onMouseLeave={handleSearchMouseLeave}
      >
        <div style={styles.searchRowSimple}>
          <input
            style={styles.searchInput}
            placeholder="Search vehicles..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            onKeyDown={handleSearchKeyDown}
            onFocus={handleSearchHover}
          />
          <button
            type="button"
            style={styles.searchButton}
            onClick={handleSearchStart}
          >
            Search
          </button>
        </div>

        {showSearchForm && (
          <div style={styles.advancedForm}>
            <div style={styles.formHeader}>
              <h3 style={styles.formTitle}>Refine your search</h3>
              <p style={styles.formText}>Use one or more filters below to search by name, location, city, pincode, or area.</p>
            </div>
            <div style={styles.formGrid}>
              <div style={styles.formField}>
                <label style={styles.formLabel}>Vehicle Name</label>
                <input
                  style={styles.formInput}
                  value={searchFilters.name}
                  onChange={(e) => handleFilterChange("name", e.target.value)}
                  placeholder="e.g. Honda Activa"
                />
              </div>
              <div style={styles.formField}>
                <label style={styles.formLabel}>Location</label>
                <input
                  style={styles.formInput}
                  value={searchFilters.location}
                  onChange={(e) => handleFilterChange("location", e.target.value)}
                  placeholder="e.g. MG Road"
                />
              </div>
              <div style={styles.formField}>
                <label style={styles.formLabel}>City</label>
                <input
                  style={styles.formInput}
                  value={searchFilters.city}
                  onChange={(e) => handleFilterChange("city", e.target.value)}
                  placeholder="e.g. Bangalore"
                />
              </div>
              <div style={styles.formField}>
                <label style={styles.formLabel}>Pincode</label>
                <input
                  style={styles.formInput}
                  value={searchFilters.pincode}
                  onChange={(e) => handleFilterChange("pincode", e.target.value)}
                  placeholder="e.g. 560001"
                />
              </div>
              <div style={styles.formField}>
                <label style={styles.formLabel}>Area</label>
                <input
                  style={styles.formInput}
                  value={searchFilters.area}
                  onChange={(e) => handleFilterChange("area", e.target.value)}
                  placeholder="e.g. Indiranagar"
                />
              </div>
            </div>
            <div style={styles.formActions}>
              <button style={styles.searchButton} onClick={() => setShowSearchForm(true)}>
                Apply Filters
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );

  return (
    <div style={{ display: "flex" }}>
      <Sidebar active={active} onSelect={(k) => setActive(k)} />
      <div style={styles.page}>
        <header style={styles.header}>
          <div style={styles.brand}>
            <div style={styles.logo}>VehicleHub</div>
            <div style={styles.tagline}>Ride Anytime, Anywhere</div>
          </div>
          <div style={styles.userPanel}>
            <div style={styles.userAvatar}>RK</div>
            <div>
              <div style={styles.userName}>Rahul Kumar</div>
              <div style={styles.userRole}>Customer</div>
            </div>
            <button style={styles.logoutButton} onClick={onLogout}>Logout</button>
          </div>
        </header>


        <main style={styles.mainGrid}>
              <SearchPanel />

          <section style={{ ...styles.panel, ...styles.fullWidthSection, ...styles.statsSection }}>
            <div style={styles.statsRow}>
              {dashboardStats.map((item) => (
                <div key={item.label} style={styles.statCard}>
                  <div style={{ ...styles.statIcon, background: item.accent + "22", color: item.accent }}>
                    {item.icon}
                  </div>
                  <div>
                    <div style={styles.statLabel}>{item.label}</div>
                    <div style={styles.statValue}>{item.value}</div>
                    <div style={styles.statSub}>{item.action}</div>
                  </div>
                </div>
              ))}
            </div>
          </section>

          <section style={{ ...styles.panel, ...styles.fullWidthSection, ...styles.dashboardOfferSection }}>
            <div style={styles.offerHeader}>
              <div>
                <h3 style={styles.panelTitle}>Today's Offers</h3>
                <p style={styles.panelText}>Automatic owner-only offers for bike, car, SUV and truck rentals.</p>
              </div>
            </div>
            <div style={styles.offersCarousel}>
              <button type="button" style={styles.carouselArrow} onClick={handlePrevOffer}>
                &lt;
              </button>
              <div style={styles.offerSlide}>
                <span style={styles.offerChip}>{dashboardOffers[offerIndex].tag}</span>
                <h4 style={styles.offerTitle}>{dashboardOffers[offerIndex].title}</h4>
                <p style={styles.offerSubtitle}>{dashboardOffers[offerIndex].subtitle}</p>
                <p style={styles.offerDetail}>{dashboardOffers[offerIndex].detail}</p>
                <div style={styles.offerMeta}>
                  <span>{offerIndex + 1} of {dashboardOffers.length}</span>
                </div>
              </div>
              <button type="button" style={styles.carouselArrow} onClick={handleNextOffer}>
                &gt;
              </button>
            </div>
          </section>

          <section style={{ ...styles.panel, ...styles.fullWidthSection, ...styles.popularSection }}>
            <div style={styles.offerHeader}>
              <div>
                <h3 style={styles.panelTitle}>Popular Vehicles</h3>
                <p style={styles.panelText}>Browse top customer favorites with availability, charges, and quick access.</p>
              </div>
            </div>
            <div style={styles.popularGrid}>
              {popularVehicles.map((vehicle) => (
                <div key={vehicle.name} style={styles.popularCard}>
                  <button type="button" style={styles.heartButton} aria-label="Like vehicle">
                    ❤
                  </button>
                  <div style={styles.popularImageWrapper}>
                    <img src={vehicle.imageUrl} alt={vehicle.name} style={styles.popularImage} />
                  </div>
                  <div style={styles.popularCardContent}>
                    <h4 style={styles.popularCardTitle}>{vehicle.name}</h4>
                    <p style={styles.popularCardSubtitle}>{vehicle.type}</p>
                    <p style={styles.popularCardInfo}>{vehicle.description}</p>
                    <div style={styles.popularCardFooter}>
                      <button type="button" style={styles.viewDetailsButton} onClick={onViewDetails}>
                        View Details
                      </button>
                      <span style={styles.popularPrice}>{vehicle.price}</span>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </section>

          <section style={{ ...styles.panel, ...styles.fullWidthSection, ...styles.popularSection }}>
            <div style={styles.offerHeader}>
              <div>
                <h3 style={styles.panelTitle}>Recently Bookings</h3>
                <p style={styles.panelText}>See the same vehicle card layout for the latest bookings.</p>
              </div>
            </div>
            <div style={styles.popularGrid}>
              {recentBookings.map((vehicle) => (
                <div key={vehicle.name} style={styles.popularCard}>
                  <button type="button" style={styles.heartButton} aria-label="Like vehicle">
                    ❤
                  </button>
                  <div style={styles.popularImageWrapper}>
                    <img src={vehicle.imageUrl} alt={vehicle.name} style={styles.popularImage} />
                  </div>
                  <div style={styles.popularCardContent}>
                    <h4 style={styles.popularCardTitle}>{vehicle.name}</h4>
                    <p style={styles.popularCardSubtitle}>{vehicle.type}</p>
                    <p style={styles.popularCardInfo}>{vehicle.description}</p>
                    <div style={styles.popularCardFooter}>
                      <button type="button" style={styles.viewDetailsButton} onClick={onViewDetails}>
                        View Details
                      </button>
                      <span style={styles.popularPrice}>{vehicle.price}</span>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </section>
        </main>
      </div>
    </div>
  );
}

const styles = {
  page: {
    minHeight: "100vh",
    maxHeight: "100vh",
    overflowY: "auto",
    overflowX: "hidden",
    background: "#f4f7fb",
    padding: "24px",
    fontFamily: "Inter, sans-serif",
    color: "#1a1f3d",
    marginLeft: 260,
    width: "calc(100% - 260px)",
    boxSizing: "border-box",
  },
  header: {
    display: "flex",
    justifyContent: "space-between",
    alignItems: "center",
    marginBottom: "24px",
  },
  brand: {
    display: "flex",
    flexDirection: "column",
  },
  logo: {
    fontSize: "28px",
    fontWeight: 800,
    color: "#0f7a34",
  },
  tagline: {
    marginTop: "6px",
    color: "#55606c",
  },
  userPanel: {
    display: "flex",
    alignItems: "center",
    gap: "12px",
  },
  userAvatar: {
    width: "48px",
    height: "48px",
    borderRadius: "50%",
    background: "#0f7a34",
    color: "white",
    display: "grid",
    placeItems: "center",
    fontWeight: 700,
  },
  userName: {
    fontWeight: 700,
  },
  userRole: {
    fontSize: "13px",
    color: "#55606c",
  },
  logoutButton: {
    marginLeft: "12px",
    background: "#fff",
    border: "1px solid #d4d7dd",
    borderRadius: "8px",
    padding: "10px 14px",
    cursor: "pointer",
  },
  statsSection: {
    marginTop: "20px",
  },
  statsRow: {
    display: "grid",
    gridTemplateColumns: "repeat(4, minmax(0, 1fr))",
    gap: "16px",
    marginBottom: "24px",
  },
  statCard: {
    background: "#ffffff",
    borderRadius: "20px",
    padding: "20px",
    boxShadow: "0 10px 30px rgba(15, 122, 52, 0.05)",
    display: "flex",
    alignItems: "center",
    gap: "16px",
  },
  statIcon: {
    width: "48px",
    height: "48px",
    borderRadius: "16px",
    display: "grid",
    placeItems: "center",
    fontSize: "1.35rem",
  },
  statLabel: {
    color: "#6f7c92",
    fontSize: "13px",
    marginBottom: "10px",
  },
  statValue: {
    fontSize: "28px",
    fontWeight: 700,
  },
  statSub: {
    marginTop: "10px",
    color: "#0f7a34",
    fontWeight: 700,
    fontSize: "12px",
  },
  mainGrid: {
    display: "grid",
    gridTemplateColumns: "repeat(2, minmax(0, 1fr))",
    gap: "24px",
  },
  fullWidthSection: {
    gridColumn: "1 / -1",
  },
  sidePanel: {
    display: "flex",
    flexDirection: "column",
    minHeight: "420px",
    maxHeight: "420px",
    overflow: "hidden",
  },
  panel: {
    background: "white",
    borderRadius: "24px",
    padding: "24px",
    boxShadow: "0 20px 40px rgba(31, 45, 73, 0.06)",
  },
  panelHeader: {
    display: "flex",
    justifyContent: "space-between",
    alignItems: "center",
    marginBottom: "20px",
    gap: "12px",
  },
  panelTitle: {
    margin: 0,
    fontSize: "20px",
  },
  panelText: {
    color: "#6f7c92",
    marginTop: "6px",
    fontSize: "14px",
  },
  actionButton: {
    padding: "12px 18px",
    borderRadius: "14px",
    border: "none",
    background: "#0f7a34",
    color: "white",
    cursor: "pointer",
  },
  searchTabs: {
    display: "flex",
    gap: "10px",
    flexWrap: "wrap",
    marginBottom: "18px",
  },
  tabButton: {
    padding: "10px 14px",
    borderRadius: "12px",
    border: "1px solid #d5d9e4",
    background: "#f7fafc",
    cursor: "pointer",
    color: "#55606c",
  },
  tabActive: {
    background: "#e6f5ea",
    borderColor: "#c8e6d8",
    color: "#0f7a34",
  },
  searchRow: {
    display: "grid",
    gridTemplateColumns: "1.3fr 1fr 1fr",
    gap: "14px",
    marginBottom: "20px",
  },
  searchWrapper: {
    display: "grid",
    gap: "16px",
  },
  searchRowSimple: {
    display: "grid",
    gridTemplateColumns: "1fr auto",
    gap: "14px",
    marginTop: "16px",
  },
  advancedForm: {
    marginTop: "22px",
    padding: "22px",
    background: "#f7fafc",
    borderRadius: "20px",
    border: "1px solid #e6edf3",
    boxShadow: "0 10px 30px rgba(15, 122, 52, 0.06)",
  },
  formHeader: {
    marginBottom: "18px",
  },
  formTitle: {
    margin: 0,
    fontSize: "18px",
  },
  formText: {
    margin: "8px 0 0",
    color: "#6f7c92",
    fontSize: "14px",
  },
  formGrid: {
    display: "grid",
    gridTemplateColumns: "repeat(auto-fit, minmax(220px, 1fr))",
    gap: "16px",
  },
  formField: {
    display: "grid",
    gap: "8px",
  },
  formLabel: {
    fontSize: "13px",
    color: "#55606c",
    fontWeight: 700,
  },
  formInput: {
